def check_Consecutive(l):
    """Write a python function to check whether the given list contains consecutive numbers or not.

    The elements are considered consecutive when, ignoring their order in
    the list, they form a run of numbers with no gaps and no duplicates
    (e.g. ``[3, 1, 2]`` is consecutive). An empty list is not consecutive,
    while a single-element list is trivially consecutive.
    """
    if not l:
        return False
    ordered = sorted(l)
    return all(
        current - previous == 1
        for previous, current in zip(ordered, ordered[1:])
    )
